# Look for all tuple unpacking of function calls across the codebase
import ast, os, re

calls = {}  # func_name -> [(file, line, num_unpacked)]

for root, dirs, files in os.walk('nanobot'):
    dirs[:] = [d for d in dirs if d != '__pycache__']
    for f in files:
        if not f.endswith('.py'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            try:
                tree = ast.parse(fh.read(), filename=path)
            except:
                continue

        for node in ast.walk(tree):
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Tuple) and isinstance(node.value, ast.Call):
                        func_name = None
                        if isinstance(node.value.func, ast.Name):
                            func_name = node.value.func.id
                        elif isinstance(node.value.func, ast.Attribute):
                            func_name = node.value.func.attr
                        if func_name:
                            n = len(target.elts)
                            key = (func_name, path)
                            if key not in calls:
                                calls[key] = []
                            calls[key].append(n)

# Report inconsistencies
for (func, path), counts in calls.items():
    if len(set(counts)) > 1:
        print(f'INCONSISTENT: {func} in {path} unpacked as {counts}')
    elif max(counts) > 1:
        print(f'OK: {func} in {path} always unpacked as {max(counts)}-tuple')
