import ast, os

for root, dirs, files in os.walk('nanobot'):
    dirs[:] = [d for d in dirs if d != '__pycache__']
    for f in files:
        if not f.endswith('.py'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            lines = fh.readlines()

        for i, line in enumerate(lines):
            stripped = line.strip()
            # Check for 'return False' followed by 'return v' pattern (dead code)
            if stripped == 'return False':
                if i + 1 < len(lines):
                    next_line = lines[i+1].strip()
                    if next_line.startswith('return ') and next_line != 'return False':
                        print(f'DEAD CODE: {path}:{i+1} - return False before {next_line}')
